'use strict';

const assert = require('assert');
const crypto = require('crypto');

const INDEX = Symbol('index');
const ALL_REAL_SERVER_MAP = Symbol('allRealServerMap');
const BUILD_WEIGHTED_REAL_SERVERS = Symbol('VipDomain#buildWeightedRealServers');

class VipDomainWithWeight {
  constructor(data) {
    assert(data, 'new VipDomain(data): data is required');

    this._data = data;
    this.weightedRealServers = [];
    this.weightedAllRealServers = [];
    this.availableRealServers = [];
    this.allRealServers = [];

    this[BUILD_WEIGHTED_REAL_SERVERS]();
    this[INDEX] = crypto.randomBytes(2).readUIntBE(0, 2);
  }

  [BUILD_WEIGHTED_REAL_SERVERS]() {
    const realServers = this._data.realNodes || [];

    const totalCount = realServers.length;
    let availableCount = 0;
    realServers.forEach(realServer => {
      const repeatedServers = Array(realServer.weight).fill(realServer);
      if (realServer.available) {
        availableCount++;
        this.weightedRealServers = this.weightedRealServers.concat(repeatedServers);
        this.availableRealServers.push(realServer);
      }
      this.weightedAllRealServers = this.weightedAllRealServers.concat(repeatedServers);
      this.allRealServers.push(realServer);
    });

    const protectThreshold = this._data.protectThreshold || 0;
    if (protectThreshold > 0) { // //开启了保护
      const leastAvailableCount = Math.ceil(totalCount * protectThreshold / 100) || 1;
      if (availableCount < leastAvailableCount) {
        const unavailbleNodes = this._getUnavailableList(leastAvailableCount - availableCount);
        unavailbleNodes.forEach(realServer => {
          const repeatedServers = Array(realServer.weight).fill(realServer);
          this.weightedRealServers = this.weightedRealServers.concat(repeatedServers);
          this.availableRealServers.push(realServer);
        });
      }
    } else {
      if (availableCount === 0) {
        realServers.forEach(realServer => {
          const repeatedServers = Array(realServer.weight).fill(realServer);
          this.weightedRealServers = this.weightedRealServers.concat(repeatedServers);
          this.availableRealServers.push(realServer);
        });
      }
    }
  }

  getRealServer() {
    const servers = this.weightedRealServers;
    this[INDEX]++;
    const index = this[INDEX] = this[INDEX] % servers.length;
    return servers[index];
  }

  getAvailableRealServers() {
    return this.availableRealServers;
  }

  _getUnavailableList(count) {
    const arr = [];
    const realServers = this._data.realNodes || [];
    for (const server of realServers) {
      if (!server.available) {
        arr.push(server);
      }

      if (arr.length >= count) {
        break;
      }
    }

    return arr;
  }

  toJSON() {
    return this._data;
  }

  changed(data) {
    return JSON.stringify(this) !== JSON.stringify(data);
  }

  get _allRealServerMap() {
    if (!this[ALL_REAL_SERVER_MAP]) {
      this[ALL_REAL_SERVER_MAP] = {};
      this.allRealServers.forEach(realServer => {
        this[ALL_REAL_SERVER_MAP][realServer.ip] = realServer;
      });
    }

    return this[ALL_REAL_SERVER_MAP];
  }

  // 是否存在指定 ip 的 realServer
  exist(ip) {
    return !!this._allRealServerMap[ip];
  }

  // 计算被下线的 realServer
  getOfflineRealServers(oldVipDomain) {
    if (!oldVipDomain) return null;

    const offlineRealServers = [];
    oldVipDomain.allRealServers.forEach(realServer => {
      if (!this.exist(realServer.ip)) offlineRealServers.push(realServer);
    });
    return offlineRealServers.length > 0 ? offlineRealServers : null;
  }
}

module.exports = VipDomainWithWeight;
